// ─── Initial Trend Generator ──────────────────────────────────────────────────
const generateInitialTrend = (): MonthlyEntry[] => {
  const monthsArray: MonthlyEntry[] = [];
  const currentDate = new Date();
  const monthNames = ["Jan", "Feb", "Mar", "Apr", "Mei", "Jun", "Jul", "Agu", "Sep", "Okt", "Nov", "Des"];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(currentDate.getFullYear(), currentDate.getMonth() - i, 1);
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, "0");
    const monthStr = `${yyyy}-${mm}`;
    const monthLabel = `${monthNames[d.getMonth()]} ${yyyy}`;
    monthsArray.push({
      bulan: monthStr,
      bulanLabel: monthLabel,
      pemasukan: 0,
      pengeluaran: 0,
    });
  }
  return monthsArray;
};

// ─── Mini Bar Chart ──────────────────────────────────────────────────────────
function MiniBarChart({
  data,
  showMasuk = true,
  showKeluar = true,
}: {
  data: MonthlyEntry[];
  showMasuk?: boolean;
  showKeluar?: boolean;
}) {
  const maxVal = Math.max(
    1,
    ...data.map((m) =>
      Math.max(showMasuk ? m.pemasukan : 0, showKeluar ? m.pengeluaran : 0)
    )
  );

  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);
  const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });

  const handleMouseMove = (e: React.MouseEvent, index: number) => {
    const container = e.currentTarget.parentElement?.parentElement?.getBoundingClientRect();
    if (container) {
      setTooltipPos({
        x: e.clientX - container.left + 14,
        y: e.clientY - container.top - 74,
      });
    }
    setHoveredIdx(index);
  };

  return (
    <Box sx={{ width: "100%", height: 120, position: "relative", mt: 2 }}>
      {[0, 0.25, 0.5, 0.75, 1].map((ratio) => (
        <Box
          key={ratio}
          sx={{
            position: "absolute",
            left: 0,
            right: 0,
            bottom: `calc(${ratio * 100}% + 20px)`,
            borderTop: "1px dashed rgba(255,255,255,0.04)",
          }}
        />
      ))}
      <Box sx={{ position: "absolute", inset: 0, display: "flex", alignItems: "flex-end", gap: "4px" }}>
        {data.map((m, i) => {
          const incH = showMasuk ? (m.pemasukan / maxVal) * 100 : 0;
          const expH = showKeluar ? (m.pengeluaran / maxVal) * 100 : 0;
          const isLast = i === data.length - 1;
          const isHovered = hoveredIdx === i;

          return (
            <Box
              key={m.bulan}
              onMouseMove={(e) => handleMouseMove(e, i)}
              onMouseEnter={() => setHoveredIdx(i)}
              onMouseLeave={() => setHoveredIdx(null)}
              sx={{
                flex: 1,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "flex-end",
                height: "100%",
                cursor: "pointer",
                position: "relative",
                zIndex: isHovered ? 2 : 1,
                transition: "opacity 0.2s ease",
                opacity: hoveredIdx === null || isHovered ? 1 : 0.4,
              }}
            >
              <Box sx={{ width: "100%", display: "flex", alignItems: "flex-end", gap: "2px", height: "calc(100% - 20px)" }}>
                {showMasuk && (
                  <Box
                    sx={{
                      flex: 1,
                      height: `${incH}%`,
                      backgroundColor: isLast ? "#6366f1" : "rgba(99,102,241,0.3)",
                      borderRadius: "3px 3px 0 0",
                      minHeight: m.pemasukan > 0 ? 3 : 0,
                      transition: "height 0.3s ease, background-color 0.2s ease",
                      ...(isHovered && {
                        backgroundColor: "#818cf8",
                        boxShadow: "0 0 10px rgba(99,102,241,0.5)",
                      }),
                    }}
                  />
                )}
                {showKeluar && (
                  <Box
                    sx={{
                      flex: 1,
                      height: `${expH}%`,
                      backgroundColor: isLast ? "#ef4444" : "rgba(239,68,68,0.25)",
                      borderRadius: "3px 3px 0 0",
                      minHeight: m.pengeluaran > 0 ? 3 : 0,
                      transition: "height 0.3s ease, background-color 0.2s ease",
                      ...(isHovered && {
                        backgroundColor: "#f87171",
                        boxShadow: "0 0 10px rgba(239,68,68,0.5)",
                      }),
                    }}
                  />
                )}
              </Box>
              <Typography sx={{ fontSize: "0.6rem", color: isLast || isHovered ? "#94a3b8" : "#475569", fontWeight: isLast || isHovered ? 700 : 400, lineHeight: 1, height: 16, mt: "2px" }}>
                {m.bulanLabel.split(" ")[0]}
              </Typography>
            </Box>
          );
        })}
      </Box>

      {/* Cursor-Following Hover Tooltip */}
      {hoveredIdx !== null && (
        <Paper
          elevation={4}
          sx={{
            position: "absolute",
            left: tooltipPos.x,
            top: tooltipPos.y,
            pointerEvents: "none",
            zIndex: 20,
            backgroundColor: "rgba(15, 23, 42, 0.95)",
            border: "1px solid rgba(255, 255, 255, 0.08)",
            borderRadius: "8px",
            p: 1.25,
            minWidth: 140,
            backdropFilter: "blur(4px)",
            boxShadow: "0 10px 15px -3px rgba(0, 0, 0, 0.5)",
            transition: "none",
          }}
        >
          <Typography sx={{ fontSize: "0.7rem", fontWeight: 700, color: "#64748b", textTransform: "uppercase", mb: 0.5 }}>
            {data[hoveredIdx].bulanLabel}
          </Typography>
          {showMasuk && (
            <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 1.5, mb: 0.25 }}>
              <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
                <Box sx={{ width: 6, height: 6, borderRadius: "50%", backgroundColor: "#6366f1" }} />
                <Typography sx={{ fontSize: "0.7rem", color: "#cbd5e1" }}>Pemasukan</Typography>
              </Box>
              <Typography sx={{ fontSize: "0.7rem", fontWeight: 700, color: "#818cf8" }}>
                {formatIDR(data[hoveredIdx].pemasukan)}
              </Typography>
            </Box>
          )}
          {showKeluar && (
            <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 1.5 }}>
              <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
                <Box sx={{ width: 6, height: 6, borderRadius: "50%", backgroundColor: "#ef4444" }} />
                <Typography sx={{ fontSize: "0.7rem", color: "#cbd5e1" }}>Pengeluaran</Typography>
              </Box>
              <Typography sx={{ fontSize: "0.7rem", fontWeight: 700, color: "#f87171" }}>
                {formatIDR(data[hoveredIdx].pengeluaran)}
              </Typography>
            </Box>
          )}
        </Paper>
      )}
    </Box>
  );
}

// ─── Sparkline ───────────────────────────────────────────────────────────────
function Sparkline({ data, color }: { data: number[]; color: string }) {
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;
  const W = 80; const H = 28;
  const pts = data.map((v, i) => {
    const x = (i / (data.length - 1)) * W;
    const y = H - ((v - min) / range) * (H - 4) - 2;
    return `${x},${y}`;
  });
  const last = pts[pts.length - 1].split(",");
  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{ overflow: "visible" }}>
      <path d={`M ${pts.join(" L ")}`} fill="none" stroke={color} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" opacity="0.8" />
      <circle cx={last[0]} cy={last[1]} r="2.5" fill={color} />
    </svg>
  );
}

// ─── Main ────────────────────────────────────────────────────────────────────
export default function DashboardPage() {
  const [loading, setLoading] = useState(true);
  const [realSaldo, setRealSaldo] = useState<number | null>(null);
  const [realTx, setRealTx] = useState<TxRow[] | null>(null);
  const [realIn, setRealIn] = useState<number | null>(null);
  const [realOut, setRealOut] = useState<number | null>(null);

  const [expenseBreak, setExpenseBreak] = useState<CatBreak[]>([]);
  const [incomeBreak, setIncomeBreak] = useState<CatBreak[]>([]);
  const [trendData, setTrendData] = useState<MonthlyEntry[]>(generateInitialTrend());
  const [showMasuk, setShowMasuk] = useState(true);
  const [showKeluar, setShowKeluar] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [ratesList, setRatesList] = useState<any[]>([]);

  const handleSyncRates = async () => {
    try {
      setRefreshing(true);
      await refreshExchangeRatesAction();
      await loadData();
    } catch (err) {
      console.error("Sync error", err);
    } finally {
      setRefreshing(false);
    }
  };

  const loadData = async () => {
    try {
      const rateRes = await getLatestRatesAction();
      const ratesMap: Record<string, number> = {};
      if (rateRes.success && Array.isArray(rateRes.data)) {
        setRatesList(rateRes.data);
        rateRes.data.forEach((r: any) => {
          if (r.rate) ratesMap[r.code] = r.rate;
        });
      }
      if (!ratesMap['USD']) ratesMap['USD'] = 1;
      const idrRate = ratesMap['IDR'] || 17364;

      const accRes = await getAccountsAction();
      const accs: any[] = accRes.success ? (accRes.data as any[]) : [];
      
      const accountMap: Record<number, { currency: string }> = {};
      accs.forEach(a => { accountMap[a.id] = { currency: a.currency || "IDR" }; });

      const toIDR = (amt: number, accountId?: number) => {
        const currency = (accountId && accountMap[accountId]?.currency) || "IDR";
        const rate = ratesMap[currency] || (currency === "USD" ? 1 : null);
        if (!rate) return amt;
        return (amt / rate) * idrRate;
      };

      const total = accs.reduce((sum, a) => {
        const balance = Number(a.saldo || a.balance) || 0;
        return sum + toIDR(balance, a.id);
      }, 0);
      setRealSaldo(total);

      const incRes = await getIncomeListAction({ pageSize: 5000 });
      const incomes: any[] = incRes.success ? (incRes.data?.items as any[]) || [] : [];

      const outRes = await getOutcomeListAction({ pageSize: 5000 });
      const outcomes: any[] = outRes.success ? (outRes.data?.items as any[]) || [] : [];

      const sumIn = incomes.reduce((sum, i) => sum + toIDR(Number(i.amount) || 0, i.accountId), 0);
      const sumOut = outcomes.reduce((sum, o) => sum + toIDR(Number(o.amount) || 0, o.accountId), 0);
      setRealIn(sumIn);
      setRealOut(sumOut);

      const merged: TxRow[] = [
        ...incomes.map((i) => ({
          id: `INC-${i.id}`,
          tanggal: i.date,
          keterangan: i.description || i.categoryName || "Pemasukan",
          tipe: "Pemasukan" as const,
          kategori: i.categoryName || "Lainnya",
          nominal: toIDR(Number(i.amount) || 0, i.accountId),
        })),
        ...outcomes.map((o) => ({
          id: `OUT-${o.id}`,
          tanggal: o.date,
          keterangan: o.description || o.categoryName || "Pengeluaran",
          tipe: "Pengeluaran" as const,
          kategori: o.categoryName || "Lainnya",
          nominal: toIDR(Number(o.amount) || 0, o.accountId),
        })),
      ].sort((a, b) => new Date(b.tanggal).getTime() - new Date(a.tanggal).getTime());

      setRealTx(merged.slice(0, 7));

      const expenseGroups: Record<string, number> = {};
      outcomes.forEach((o) => {
        const catName = o.categoryName || "Lainnya";
        expenseGroups[catName] = (expenseGroups[catName] || 0) + toIDR(Number(o.amount) || 0, o.accountId);
      });
      const colorList = ["#f59e0b", "#3b82f6", "#8b5cf6", "#ec4899", "#10b981", "#64748b"];
      const calculatedExpense = Object.entries(expenseGroups).map(([kategori, nominal], index) => ({
        kategori,
        nominal,
        persen: sumOut > 0 ? parseFloat(((nominal / sumOut) * 100).toFixed(1)) : 0,
        color: colorList[index % colorList.length],
      })).sort((a, b) => b.nominal - a.nominal);
      setExpenseBreak(calculatedExpense);

      const incomeGroups: Record<string, number> = {};
      incomes.forEach((i) => {
        const catName = i.categoryName || "Lainnya";
        incomeGroups[catName] = (incomeGroups[catName] || 0) + toIDR(Number(i.amount) || 0, i.accountId);
      });
      const calculatedIncome = Object.entries(incomeGroups).map(([kategori, nominal], index) => ({
        kategori,
        nominal,
        persen: sumIn > 0 ? parseFloat(((nominal / sumIn) * 100).toFixed(1)) : 0,
        color: colorList[index % colorList.length],
      })).sort((a, b) => b.nominal - a.nominal);
      setIncomeBreak(calculatedIncome);

      const trendArray = generateInitialTrend();
      incomes.forEach((i) => {
        if (!i.date) return;
        const dObj = new Date(i.date);
        const yyyy = dObj.getFullYear();
        const mm = String(dObj.getMonth() + 1).padStart(2, "0");
        const mStr = `${yyyy}-${mm}`;
        const match = trendArray.find((m) => m.bulan === mStr);
        if (match) match.pemasukan += toIDR(Number(i.amount) || 0, i.accountId);
      });
      outcomes.forEach((o) => {
        if (!o.date) return;
        const dObj = new Date(o.date);
        const yyyy = dObj.getFullYear();
        const mm = String(dObj.getMonth() + 1).padStart(2, "0");
        const mStr = `${yyyy}-${mm}`;
        const match = trendArray.find((m) => m.bulan === mStr);
        if (match) match.pengeluaran += toIDR(Number(o.amount) || 0, o.accountId);
      });
      setTrendData(trendArray);
      setLoading(false);
    } catch (err) {
      console.error("loadDashboardData error", err);
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();

    const handleRefresh = () => {
      loadData();
    };

    window.addEventListener("refresh-data", handleRefresh);
    return () => {
      window.removeEventListener("refresh-data", handleRefresh);
    };
  }, []);

  const currentMonth = trendData[trendData.length - 1] || { bulan: "", bulanLabel: "", pemasukan: 0, pengeluaran: 0 };
  const prevMonth = trendData[trendData.length - 2] || { bulan: "", bulanLabel: "", pemasukan: 0, pengeluaran: 0 };

  const currentMonthName = currentMonth.bulanLabel ? currentMonth.bulanLabel.split(" ")[0] : "—";
  const currentMonthNum = currentMonth.bulan ? parseInt(currentMonth.bulan.split("-")[1]) : new Date().getMonth() + 1;
  const currentYear = currentMonth.bulan ? currentMonth.bulan.split("-")[0] : new Date().getFullYear();
  const quarterLabel = `Q${Math.ceil(currentMonthNum / 3)} · ${currentYear}`;

  const totalPemasukan = realIn !== null ? realIn : 0;
  const totalPengeluaran = realOut !== null ? realOut : 0;
  const netIncome = totalPemasukan - totalPengeluaran;
  const saldoAkhir = realSaldo !== null ? realSaldo : 0;
  const savingRate = totalPemasukan > 0 ? ((netIncome / totalPemasukan) * 100).toFixed(1) : "0.0";
  const rasioPengeluaran = totalPemasukan > 0 ? ((totalPengeluaran / totalPemasukan) * 100).toFixed(1) : "0.0";

  const incGrowth = prevMonth.pemasukan > 0 ? (((currentMonth.pemasukan - prevMonth.pemasukan) / prevMonth.pemasukan) * 100).toFixed(1) : "0.0";
  const expGrowth = prevMonth.pengeluaran > 0 ? (((currentMonth.pengeluaran - prevMonth.pengeluaran) / prevMonth.pengeluaran) * 100).toFixed(1) : "0.0";

  const incTrend = trendData.map((m) => m.pemasukan);
  const expTrend = trendData.map((m) => m.pengeluaran);
  const netTrend = trendData.map((m) => m.pemasukan - m.pengeluaran);

  return (
    <Box sx={{ p: { xs: 3, md: 4 }, minHeight: "100vh" }}>
      {/* Header */}
      <Box sx={{ mb: 4, display: "flex", alignItems: "flex-start", justifyContent: "space-between" }}>
        <Box>
          <Typography sx={{ fontSize: "0.7rem", fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#6366f1", mb: 0.5 }}>
            Overview · {currentMonth.bulanLabel}
          </Typography>
          <Typography sx={{ fontSize: "1.5rem", fontWeight: 800, color: "#f1f5f9", lineHeight: 1.2 }}>
            Financial Dashboard
          </Typography>
          <Typography sx={{ fontSize: "0.8125rem", color: "#475569", mt: 0.5 }}>
            Ringkasan keuangan {quarterLabel}
          </Typography>
        </Box>
        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <Tooltip title="Perbarui Nilai Tukar Mata Uang">
            <IconButton onClick={handleSyncRates} disabled={refreshing || loading} size="small"
              sx={{ border: "1px solid rgba(255,255,255,0.06)", backgroundColor: "#0f1e38", color: "#64748b", "&:hover": { color: "#fff", backgroundColor: "#1e293b" } }}>
              <Sync sx={{ fontSize: 16, animation: refreshing ? "spin 1s linear infinite" : "none", "@keyframes spin": { "0%": { transform: "rotate(0deg)" }, "100%": { transform: "rotate(360deg)" } } }} />
            </IconButton>
          </Tooltip>
          <Box sx={{ px: 2, py: 1.25, borderRadius: "12px", border: "1px solid rgba(255,255,255,0.06)", backgroundColor: "#0f1e38" }}>
            <Typography sx={{ fontSize: "0.6875rem", color: "#475569", mb: 0.25 }}>Periode Aktif</Typography>
            <Typography sx={{ fontSize: "0.9375rem", fontWeight: 700, color: "#e2e8f0" }}>{quarterLabel}</Typography>
          </Box>
        </Box>
      </Box>

      {/* KPI Cards */}
      <Box sx={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 2, mb: 3 }}>
        <Paper elevation={0} sx={{ p: 2.5, borderRadius: "16px", background: "linear-gradient(135deg, #1e1b4b 0%, #2e1065 100%)", border: "1px solid rgba(99,102,241,0.3)", position: "relative", overflow: "hidden" }}>
          <Box sx={{ position: "absolute", top: -24, right: -24, width: 90, height: 90, borderRadius: "50%", backgroundColor: "rgba(99,102,241,0.12)" }} />
          <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", mb: 1.5 }}>
            <Typography sx={{ fontSize: "0.7rem", color: "#a5b4fc", fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em" }}>Net Worth</Typography>
            <Box sx={{ width: 30, height: 30, borderRadius: "8px", backgroundColor: "rgba(99,102,241,0.25)", display: "flex", alignItems: "center", justifyContent: "center" }}>
              <AccountBalance sx={{ fontSize: 15, color: "#a5b4fc" }} />
            </Box>
          </Box>
          {loading ? (
            <Skeleton variant="rectangular" height={32} width={140} sx={{ bgcolor: "rgba(255,255,255,0.12)", my: 0.5, borderRadius: "6px" }} />
          ) : (
            <Typography sx={{ fontSize: "1.5rem", fontWeight: 800, color: "#e0e7ff", lineHeight: 1.1, mb: 0.5 }}>{formatIDR(saldoAkhir)}</Typography>
          )}
        </Paper>

        <Paper elevation={0} sx={{ p: 2.5, borderRadius: "16px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)" }}>
          <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", mb: 1 }}>
            <Typography sx={{ fontSize: "0.7rem", color: "#64748b", fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em" }}>Total Pemasukan</Typography>
            {loading ? (
              <Skeleton variant="rectangular" height={16} width={60} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "4px" }} />
            ) : (
              <Sparkline data={incTrend} color="#22c55e" />
            )}
          </Box>
          {loading ? (
            <Skeleton variant="rectangular" height={28} width={110} sx={{ bgcolor: "rgba(255,255,255,0.06)", my: 0.5, borderRadius: "6px" }} />
          ) : (
            <Typography sx={{ fontSize: "1.375rem", fontWeight: 800, color: "#22c55e", lineHeight: 1.1, mb: 0.5 }}>{formatCompact(totalPemasukan)}</Typography>
          )}
          {loading ? (
            <Skeleton variant="text" width={100} sx={{ bgcolor: "rgba(255,255,255,0.06)" }} />
          ) : (
            <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
              <TrendingUp sx={{ fontSize: 13, color: parseFloat(incGrowth) >= 0 ? "#22c55e" : "#ef4444" }} />
              <Typography sx={{ fontSize: "0.7rem", color: parseFloat(incGrowth) >= 0 ? "#22c55e" : "#ef4444", fontWeight: 600 }}>
                {parseFloat(incGrowth) >= 0 ? "+" : ""}{incGrowth}%
              </Typography>
              <Typography sx={{ fontSize: "0.7rem", color: "#475569" }}>vs bulan lalu</Typography>
            </Box>
          )}
        </Paper>

        <Paper elevation={0} sx={{ p: 2.5, borderRadius: "16px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)" }}>
          <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", mb: 1 }}>
            <Typography sx={{ fontSize: "0.7rem", color: "#64748b", fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em" }}>Total Pengeluaran</Typography>
            {loading ? (
              <Skeleton variant="rectangular" height={16} width={60} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "4px" }} />
            ) : (
              <Sparkline data={expTrend} color="#ef4444" />
            )}
          </Box>
          {loading ? (
            <Skeleton variant="rectangular" height={28} width={110} sx={{ bgcolor: "rgba(255,255,255,0.06)", my: 0.5, borderRadius: "6px" }} />
          ) : (
            <Typography sx={{ fontSize: "1.375rem", fontWeight: 800, color: "#ef4444", lineHeight: 1.1, mb: 0.5 }}>{formatCompact(totalPengeluaran)}</Typography>
          )}
          {loading ? (
            <Skeleton variant="text" width={100} sx={{ bgcolor: "rgba(255,255,255,0.06)" }} />
          ) : (
            <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
              <TrendingDown sx={{ fontSize: 13, color: parseFloat(expGrowth) <= 0 ? "#22c55e" : "#f87171" }} />
              <Typography sx={{ fontSize: "0.7rem", color: parseFloat(expGrowth) <= 0 ? "#22c55e" : "#f87171", fontWeight: 600 }}>
                {parseFloat(expGrowth) >= 0 ? "+" : ""}{expGrowth}%
              </Typography>
              <Typography sx={{ fontSize: "0.7rem", color: "#475569" }}>vs bulan lalu</Typography>
            </Box>
          )}
        </Paper>

        <Paper elevation={0} sx={{ p: 2.5, borderRadius: "16px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)" }}>
          <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", mb: 1 }}>
            <Typography sx={{ fontSize: "0.7rem", color: "#64748b", fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em" }}>Net Income</Typography>
            {loading ? (
              <Skeleton variant="rectangular" height={16} width={60} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "4px" }} />
            ) : (
              <Sparkline data={netTrend} color="#818cf8" />
            )}
          </Box>
          {loading ? (
            <Skeleton variant="rectangular" height={28} width={110} sx={{ bgcolor: "rgba(255,255,255,0.06)", my: 0.5, borderRadius: "6px" }} />
          ) : (
            <Typography sx={{ fontSize: "1.375rem", fontWeight: 800, color: "#818cf8", lineHeight: 1.1, mb: 0.5 }}>{formatCompact(netIncome)}</Typography>
          )}
          {loading ? (
            <Skeleton variant="text" width={100} sx={{ bgcolor: "rgba(255,255,255,0.06)" }} />
          ) : (
            <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
              <Savings sx={{ fontSize: 13, color: "#f59e0b" }} />
              <Typography sx={{ fontSize: "0.7rem", color: "#f59e0b", fontWeight: 700 }}>Saving Rate {savingRate}%</Typography>
            </Box>
          )}
        </Paper>
      </Box>

      {/* Row 2: Bar Chart + Expense Breakdown */}
      <Box sx={{ display: "grid", gridTemplateColumns: "1.4fr 1fr", gap: 2.5, mb: 2.5 }}>
        <Paper elevation={0} sx={{ borderRadius: "16px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)", p: 3 }}>
          <Box sx={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", mb: 0.5 }}>
            <Box>
              <Typography sx={{ fontSize: "0.9375rem", fontWeight: 700, color: "#e2e8f0" }}>Tren 6 Bulan Terakhir</Typography>
              <Typography sx={{ fontSize: "0.75rem", color: "#475569", mt: 0.25 }}>Pemasukan vs Pengeluaran</Typography>
            </Box>
            <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
              <Box
                onClick={() => setShowMasuk(!showMasuk)}
                sx={{
                  display: "flex",
                  alignItems: "center",
                  gap: 0.75,
                  cursor: "pointer",
                  opacity: showMasuk ? 1 : 0.4,
                  transition: "opacity 0.2s ease",
                  userSelect: "none",
                  "&:hover": { opacity: 0.8 }
                }}
              >
                <Box sx={{ width: 8, height: 8, borderRadius: "2px", backgroundColor: "#6366f1" }} />
                <Typography sx={{ fontSize: "0.7rem", color: "#64748b", textDecoration: showMasuk ? "none" : "line-through", fontWeight: 600 }}>Masuk</Typography>
              </Box>
              <Box
                onClick={() => setShowKeluar(!showKeluar)}
                sx={{
                  display: "flex",
                  alignItems: "center",
                  gap: 0.75,
                  cursor: "pointer",
                  opacity: showKeluar ? 1 : 0.4,
                  transition: "opacity 0.2s ease",
                  userSelect: "none",
                  "&:hover": { opacity: 0.8 }
                }}
              >
                <Box sx={{ width: 8, height: 8, borderRadius: "2px", backgroundColor: "#ef4444" }} />
                <Typography sx={{ fontSize: "0.7rem", color: "#64748b", textDecoration: showKeluar ? "none" : "line-through", fontWeight: 600 }}>Keluar</Typography>
              </Box>
            </Box>
          </Box>
          {loading ? (
            <Skeleton variant="rectangular" height={120} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "8px", mt: 2 }} />
          ) : (
            <MiniBarChart data={trendData} showMasuk={showMasuk} showKeluar={showKeluar} />
          )}
          {loading ? (
            <Box sx={{ display: "flex", gap: 3, mt: 2, pt: 2, borderTop: "1px solid rgba(255,255,255,0.05)" }}>
              <Skeleton variant="rectangular" height={24} width={120} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "4px" }} />
              <Skeleton variant="rectangular" height={24} width={120} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "4px" }} />
            </Box>
          ) : (
            <Box sx={{ display: "flex", gap: 3, mt: 2, pt: 2, borderTop: "1px solid rgba(255,255,255,0.05)" }}>
              <Box>
                <Typography sx={{ fontSize: "0.7rem", color: "#64748b", mb: 0.25 }}>{currentMonthName} · Pemasukan</Typography>
                <Typography sx={{ fontSize: "0.9375rem", fontWeight: 700, color: "#6366f1" }}>{formatIDR(currentMonth.pemasukan)}</Typography>
              </Box>
              <Box>
                <Typography sx={{ fontSize: "0.7rem", color: "#64748b", mb: 0.25 }}>{currentMonthName} · Pengeluaran</Typography>
                <Typography sx={{ fontSize: "0.9375rem", fontWeight: 700, color: "#ef4444" }}>{formatIDR(currentMonth.pengeluaran)}</Typography>
              </Box>
              <Box sx={{ ml: "auto", textAlign: "right" }}>
                <Typography sx={{ fontSize: "0.7rem", color: "#64748b", mb: 0.25 }}>Net {currentMonthName}</Typography>
                <Typography sx={{ fontSize: "0.9375rem", fontWeight: 700, color: "#22c55e" }}>+{formatIDR(currentMonth.pemasukan - currentMonth.pengeluaran)}</Typography>
              </Box>
            </Box>
          )}
        </Paper>
        <Paper elevation={0} sx={{ borderRadius: "16px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)", p: 3 }}>
          <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", mb: 2.5 }}>
            <Typography sx={{ fontSize: "0.9375rem", fontWeight: 700, color: "#e2e8f0" }}>Breakdown Pengeluaran</Typography>
            <Typography sx={{ fontSize: "0.75rem", color: "#475569" }}>{quarterLabel}</Typography>
          </Box>
          {loading ? (
            [1, 2, 3, 4, 5].map((i) => (
              <Box key={i} sx={{ mb: 2 }}>
                <Box sx={{ display: "flex", justifyContent: "space-between", mb: 0.6 }}>
                  <Skeleton variant="text" width={100} sx={{ bgcolor: "rgba(255,255,255,0.06)" }} />
                  <Skeleton variant="text" width={50} sx={{ bgcolor: "rgba(255,255,255,0.06)" }} />
                </Box>
                <Skeleton variant="rectangular" height={4} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "2px" }} />
              </Box>
            ))
          ) : expenseBreak.length === 0 ? (
            <Box sx={{ py: 6, textAlign: "center", color: "#475569", fontSize: "0.8125rem" }}>
              Belum ada data pengeluaran real di database.
            </Box>
          ) : (
            expenseBreak.map((cat) => (
              <Box key={cat.kategori} sx={{ mb: 2 }}>
                <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", mb: 0.6 }}>
                  <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                    <Box sx={{ width: 7, height: 7, borderRadius: "50%", backgroundColor: cat.color, flexShrink: 0 }} />
                    <Typography sx={{ fontSize: "0.78rem", color: "#94a3b8" }}>{cat.kategori}</Typography>
                  </Box>
                  <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
                    <Typography sx={{ fontSize: "0.78rem", color: "#e2e8f0", fontWeight: 600 }}>{formatCompact(cat.nominal)}</Typography>
                    <Typography sx={{ fontSize: "0.7rem", color: "#475569", minWidth: 34, textAlign: "right" }}>{cat.persen}%</Typography>
                  </Box>
                </Box>
                <LinearProgress variant="determinate" value={cat.persen} sx={{ height: 4, borderRadius: "2px", backgroundColor: "rgba(255,255,255,0.05)", "& .MuiLinearProgress-bar": { backgroundColor: cat.color, borderRadius: "2px" } }} />
              </Box>
            ))
          )}
        </Paper>
      </Box>

      {/* Row 3: Recent Transactions + Right Column */}
      <Box sx={{ display: "grid", gridTemplateColumns: "1.4fr 1fr", gap: 2.5 }}>
        <Paper elevation={0} sx={{ borderRadius: "16px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)", overflow: "hidden" }}>
          <Box sx={{ px: 3, py: 2, borderBottom: "1px solid rgba(255,255,255,0.05)", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
            <Typography sx={{ fontWeight: 700, color: "#e2e8f0", fontSize: "0.9375rem" }}>Transaksi Terbaru</Typography>
            <Link href="/income" style={{ textDecoration: "none" }}>
              <Button size="small" endIcon={<ArrowForward sx={{ fontSize: 13 }} />} sx={{ textTransform: "none", fontSize: "0.75rem", color: "#6366f1", fontWeight: 600, px: 1.5, py: 0.5, borderRadius: "8px", "&:hover": { backgroundColor: "rgba(99,102,241,0.1)" } }}>
                Lihat Semua
              </Button>
            </Link>
          </Box>
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell sx={headCellSx}>Tanggal</TableCell>
                  <TableCell sx={headCellSx}>Keterangan</TableCell>
                  <TableCell sx={headCellSx}>Kategori</TableCell>
                  <TableCell sx={{ ...headCellSx, textAlign: "right" }}>Nominal</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {loading ? (
                  [1, 2, 3, 4, 5].map((i) => (
                    <TableRow key={i}>
                      <TableCell sx={cellSx}><Skeleton variant="text" width={50} sx={{ bgcolor: "rgba(255,255,255,0.06)" }} /></TableCell>
                      <TableCell sx={cellSx}><Skeleton variant="text" width={150} sx={{ bgcolor: "rgba(255,255,255,0.06)" }} /></TableCell>
                      <TableCell sx={cellSx}><Skeleton variant="rectangular" height={18} width={80} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "5px" }} /></TableCell>
                      <TableCell sx={{ ...cellSx, textAlign: "right" }}><Skeleton variant="text" width={80} sx={{ bgcolor: "rgba(255,255,255,0.06)", ml: "auto" }} /></TableCell>
                    </TableRow>
                  ))
                ) : (realTx || []).length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={4} sx={{ textAlign: "center", py: 4, color: "#475569", fontSize: "0.8125rem", borderColor: "rgba(255,255,255,0.05)" }}>
                      Belum ada transaksi real di database.
                    </TableCell>
                  </TableRow>
                ) : (
                  (realTx || []).map((tx, i) => (
                    <TableRow key={tx.id} sx={{ backgroundColor: i % 2 === 0 ? "transparent" : "rgba(255,255,255,0.015)", "&:hover": { backgroundColor: "rgba(99,102,241,0.06)" }, transition: "background-color 0.15s" }}>
                      <TableCell sx={{ ...cellSx, color: "#475569", whiteSpace: "nowrap", fontSize: "0.75rem" }}>
                        {new Date(tx.tanggal).toLocaleDateString("id-ID", { day: "2-digit", month: "short" })}
                      </TableCell>
                      <TableCell sx={cellSx}>
                        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                          <Box sx={{ width: 24, height: 24, borderRadius: "7px", backgroundColor: tx.tipe === "Pemasukan" ? "rgba(34,197,94,0.12)" : "rgba(239,68,68,0.12)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                            {tx.tipe === "Pemasukan" ? <ArrowUpward sx={{ fontSize: 11, color: "#22c55e" }} /> : <ArrowDownward sx={{ fontSize: 11, color: "#ef4444" }} />}
                          </Box>
                          <Typography sx={{ fontSize: "0.8125rem", color: "#e2e8f0", fontWeight: 500 }}>{tx.keterangan}</Typography>
                        </Box>
                      </TableCell>
                      <TableCell sx={cellSx}>
                        <Chip label={tx.kategori} size="small" sx={{ fontSize: "0.6rem", height: 18, fontWeight: 600, borderRadius: "5px", backgroundColor: "rgba(71,85,105,0.4)", color: "#94a3b8" }} />
                      </TableCell>
                      <TableCell sx={{ ...cellSx, textAlign: "right", fontWeight: 700, color: tx.tipe === "Pemasukan" ? "#22c55e" : "#ef4444", whiteSpace: "nowrap" }}>
                        {tx.tipe === "Pengeluaran" ? "−" : "+"}{formatIDR(tx.nominal)}
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>


        <Box sx={{ display: "flex", flexDirection: "column", gap: 2.5 }}>
          <Paper elevation={0} sx={{ borderRadius: "16px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)", p: 3 }}>
            <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", mb: 2.5 }}>
              <Typography sx={{ fontSize: "0.9375rem", fontWeight: 700, color: "#e2e8f0" }}>Sumber Pemasukan</Typography>
              <Typography sx={{ fontSize: "0.75rem", color: "#475569" }}>{quarterLabel}</Typography>
            </Box>
            {loading ? (
              [1, 2, 3, 4, 5].map((i) => (
                <Box key={i} sx={{ mb: 1.75 }}>
                  <Box sx={{ display: "flex", justifyContent: "space-between", mb: 0.6 }}>
                    <Skeleton variant="text" width={100} sx={{ bgcolor: "rgba(255,255,255,0.06)" }} />
                    <Skeleton variant="text" width={50} sx={{ bgcolor: "rgba(255,255,255,0.06)" }} />
                  </Box>
                  <Skeleton variant="rectangular" height={4} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "2px" }} />
                </Box>
              ))
            ) : incomeBreak.length === 0 ? (
              <Box sx={{ py: 6, textAlign: "center", color: "#475569", fontSize: "0.8125rem" }}>
                Belum ada data pemasukan real di database.
              </Box>
            ) : (
              incomeBreak.map((cat) => (
                <Box key={cat.kategori} sx={{ mb: 1.75 }}>
                  <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", mb: 0.6 }}>
                    <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                      <Box sx={{ width: 7, height: 7, borderRadius: "50%", backgroundColor: cat.color, flexShrink: 0 }} />
                      <Typography sx={{ fontSize: "0.78rem", color: "#94a3b8" }}>{cat.kategori}</Typography>
                    </Box>
                    <Box sx={{ display: "flex", gap: 1.5 }}>
                      <Typography sx={{ fontSize: "0.78rem", color: "#e2e8f0", fontWeight: 600 }}>{formatCompact(cat.nominal)}</Typography>
                      <Typography sx={{ fontSize: "0.7rem", color: "#475569", minWidth: 34, textAlign: "right" }}>{cat.persen}%</Typography>
                    </Box>
                  </Box>
                  <LinearProgress variant="determinate" value={cat.persen} sx={{ height: 4, borderRadius: "2px", backgroundColor: "rgba(255,255,255,0.05)", "& .MuiLinearProgress-bar": { backgroundColor: cat.color, borderRadius: "2px" } }} />
                </Box>
              ))
            )}
          </Paper>

          <Paper elevation={0} sx={{ borderRadius: "16px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)", p: 3 }}>
            <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", mb: 2.5 }}>
              <Typography sx={{ fontSize: "0.9375rem", fontWeight: 700, color: "#e2e8f0" }}>Nilai Kurs</Typography>
              {ratesList.length > 0 && !loading && (
                <Typography sx={{ fontSize: "0.65rem", color: "#475569", fontStyle: "italic" }}>
                  Updated: {ratesList[0]?.fetchedAt ? new Date(ratesList[0].fetchedAt).toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit" }) : ""}
                </Typography>
              )}
            </Box>
            {loading ? (
              [1, 2].map((i) => (
                <Skeleton key={i} variant="rectangular" height={40} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "8px", mb: 1 }} />
              ))
            ) : ratesList.length === 0 ? (
              <Typography sx={{ color: "#475569", fontSize: "0.75rem", textAlign: "center" }}>Data kurs belum tersedia.</Typography>
            ) : (
              <Box sx={{ display: "flex", flexDirection: "column", gap: 0.75 }}>
                {ratesList.filter(r => r.code !== 'USD').map((r, idx, arr) => (
                  <Box key={r.code} sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", py: 1.25, borderBottom: idx === arr.length - 1 ? "none" : "1px solid rgba(255,255,255,0.03)" }}>
                    <Typography sx={{ fontSize: "0.8125rem", fontWeight: 700, color: "#94a3b8", letterSpacing: "0.02em" }}>
                      <span style={{ color: "#e2e8f0" }}>USD</span> / {r.code}
                    </Typography>
                    <Typography sx={{ fontSize: "0.9375rem", fontWeight: 700, color: "#f8fafc" }}>
                      {r.rate?.toLocaleString("id-ID", { maximumFractionDigits: r.code === 'IDR' ? 0 : 4 })}
                    </Typography>
                  </Box>
                ))}
              </Box>
            )}
          </Paper>

          <Paper elevation={0} sx={{ borderRadius: "16px", backgroundColor: "#0f1e38", border: "1px solid rgba(255,255,255,0.05)", p: 3 }}>
            <Typography sx={{ fontSize: "0.9375rem", fontWeight: 700, color: "#e2e8f0", mb: 2 }}>Kesehatan Keuangan</Typography>
            {loading ? (
              [1, 2, 3].map((i) => (
                <Box key={i} sx={{ py: 1.5, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                  <Box sx={{ display: "flex", alignItems: "center", gap: 1.25 }}>
                    <Skeleton variant="rectangular" height={28} width={28} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "8px" }} />
                    <Box>
                      <Skeleton variant="text" width={100} sx={{ bgcolor: "rgba(255,255,255,0.06)" }} />
                      <Skeleton variant="text" width={60} sx={{ bgcolor: "rgba(255,255,255,0.06)" }} />
                    </Box>
                  </Box>
                  <Skeleton variant="rectangular" height={22} width={60} sx={{ bgcolor: "rgba(255,255,255,0.06)", borderRadius: "6px" }} />
                </Box>
              ))
            ) : (
              [
                { label: "Saving Rate", value: `${savingRate}%`, desc: "Target ≥ 20%", ok: parseFloat(savingRate) >= 20, icon: <Savings sx={{ fontSize: 14 }} /> },
                { label: "Rasio Pengeluaran", value: `${rasioPengeluaran}%`, desc: "Target ≤ 70%", ok: totalPemasukan > 0 ? totalPengeluaran / totalPemasukan <= 0.7 : true, icon: <SwapVert sx={{ fontSize: 14 }} /> },
                { label: "Arus Kas", value: totalPemasukan === 0 && totalPengeluaran === 0 ? "Seimbang" : netIncome >= 0 ? "Positif" : "Negatif", desc: "Pemasukan > Pengeluaran", ok: netIncome >= 0, icon: <TrendingUp sx={{ fontSize: 14 }} /> },
              ].map((stat, i, arr) => (
                <Box key={stat.label}>
                  <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", py: 1.5 }}>
                    <Box sx={{ display: "flex", alignItems: "center", gap: 1.25 }}>
                      <Box sx={{ width: 28, height: 28, borderRadius: "8px", backgroundColor: stat.ok ? "rgba(34,197,94,0.1)" : "rgba(239,68,68,0.1)", display: "flex", alignItems: "center", justifyContent: "center", color: stat.ok ? "#22c55e" : "#ef4444" }}>
                        {stat.icon}
                      </Box>
                      <Box>
                        <Typography sx={{ fontSize: "0.8rem", color: "#cbd5e1", fontWeight: 500 }}>{stat.label}</Typography>
                        <Typography sx={{ fontSize: "0.68rem", color: "#475569" }}>{stat.desc}</Typography>
                      </Box>
                    </Box>
                    <Chip label={stat.value} size="small" sx={{ fontSize: "0.7rem", height: 22, fontWeight: 700, borderRadius: "6px", backgroundColor: stat.ok ? "rgba(34,197,94,0.12)" : "rgba(239,68,68,0.12)", color: stat.ok ? "#22c55e" : "#ef4444", border: `1px solid ${stat.ok ? "rgba(34,197,94,0.25)" : "rgba(239,68,68,0.25)"}` }} />
                  </Box>
                  {i < arr.length - 1 && <Divider sx={{ borderColor: "rgba(255,255,255,0.04)" }} />}
                </Box>
              ))
            )}
          </Paper>
        </Box>
      </Box>
    </Box>
  );
}